#!/usr/bin/env python3
# Generate stable XBF index name tables from StableXbfIndexes.g.h.
#
# usage: gen_stable_tables.py <StableXbfIndexes.g.h> <out-dir>
#
# The upstream header is generated by Microsoft and is MIT-licensed.  We only
# extract the enumerator names, not any code, and split them into chunks so
# that no generated Rust file exceeds the repository's 500 line limit.

import re
import sys
from pathlib import Path

CHUNK = 400


def parse_enum(text, name):
    match = re.search(r"enum class %s[^{]*\{(.*?)\};" % name, text, re.S)
    if not match:
        raise SystemExit("enum %s not found" % name)
    body = match.group(1)
    entries = []
    for item in body.split(","):
        item = item.strip()
        if not item:
            continue
        item = re.sub(r"//.*", "", item).strip()
        m = re.match(r"^(\w+)\s*=\s*(\d+)$", item)
        if not m:
            raise SystemExit("cannot parse enumerator %r" % item)
        entries.append((m.group(1), int(m.group(2))))
    entries.sort(key=lambda e: e[1])
    for i, (_, value) in enumerate(entries):
        if value != i:
            raise SystemExit("non-contiguous %s at %d" % (name, i))
    return [name for name, _ in entries]


def emit(chunks, prefix, out_dir):
    for i, chunk in enumerate(chunks):
        path = out_dir / ("%s_%d.rs" % (prefix, i))
        with path.open("w") as f:
            f.write("// Generated by tools/gen_stable_tables.py from StableXbfIndexes.g.h.\n")
            f.write("// Do not edit by hand.\n\n")
            f.write("pub static NAMES: &[&str] = &[\n")
            for name in chunk:
                f.write('    "%s",\n' % name)
            f.write("];\n")
    return len(chunks)


def main():
    if len(sys.argv) != 3:
        raise SystemExit("usage: gen_stable_tables.py <header> <out-dir>")
    text = Path(sys.argv[1]).read_text()
    out_dir = Path(sys.argv[2])
    out_dir.mkdir(parents=True, exist_ok=True)

    types = parse_enum(text, "StableXbfTypeIndex")
    props = parse_enum(text, "StableXbfPropertyIndex")

    def chunks(items):
        return [items[i:i + CHUNK] for i in range(0, len(items), CHUNK)]

    type_chunks = chunks(types)
    prop_chunks = chunks(props)
    emit(type_chunks, "types", out_dir)
    emit(prop_chunks, "props", out_dir)

    with (out_dir / "mod.rs").open("w") as f:
        f.write("/*\n")
        f.write(" * Stable XBF index tables.\n")
        f.write(" *\n")
        f.write(" * Ported from dxaml/xcp/core/Parser/StableXbfIndexes.g.h.  Trusted\n")
        f.write(" * (stable) ids in a v2 node stream index these ordered name lists\n")
        f.write(" * instead of the file's own metadata tables.\n")
        f.write(" */\n\n")
        for i in range(len(type_chunks)):
            f.write("mod types_%d;\n" % i)
        for i in range(len(prop_chunks)):
            f.write("mod props_%d;\n" % i)
        f.write("\nstatic TYPE_CHUNKS: [&[&str]; %d] = [\n" % len(type_chunks))
        for i in range(len(type_chunks)):
            f.write("    types_%d::NAMES,\n" % i)
        f.write("];\n\n")
        f.write("static PROPERTY_CHUNKS: [&[&str]; %d] = [\n" % len(prop_chunks))
        for i in range(len(prop_chunks)):
            f.write("    props_%d::NAMES,\n" % i)
        f.write("];\n\n")
        f.write("/* Look up a stable type name. */\n")
        f.write("pub fn type_name(index: u16) -> Option<&'static str> {\n")
        f.write("    lookup(&TYPE_CHUNKS, index as usize)\n")
        f.write("}\n\n")
        f.write("/* Look up a stable property name. */\n")
        f.write("pub fn property_name(index: u16) -> Option<&'static str> {\n")
        f.write("    lookup(&PROPERTY_CHUNKS, index as usize)\n")
        f.write("}\n\n")
        f.write("fn lookup(chunks: &'static [&'static [&'static str]], mut index: usize) -> Option<&'static str> {\n")
        f.write("    for chunk in chunks {\n")
        f.write("        if index < chunk.len() {\n")
        f.write("            return Some(chunk[index]);\n")
        f.write("        }\n")
        f.write("        index -= chunk.len();\n")
        f.write("    }\n")
        f.write("    None\n")
        f.write("}\n")

    print("types: %d in %d files" % (len(types), len(type_chunks)))
    print("properties: %d in %d files" % (len(props), len(prop_chunks)))


if __name__ == "__main__":
    main()
